    ["SETUP_WIZARD_HUD_BODY"] = "Recomendado. Muestra la siguiente acción de pesca con un icono y texto breve de estado para entenderla mejor de un vistazo.",
    ["SETUP_WIZARD_BUTTON_BODY"] = "Un control más pequeño solo con icono para jugadores que quieren ocupar menos espacio en pantalla.",
    ["SETUP_WIZARD_TRACKING_TITLE"] = "Registro y puntuación",
    ["SETUP_WIZARD_TRACKING_BODY"] = "El registro guarda botín y lanzamientos de pesca. La puntuación de Midnight usa esas capturas y datos del diario para mostrar progreso y objetivos útiles.",
    ["SETUP_WIZARD_KEEP_WATCH_LABEL"] = "Mantener vigilancia de puntuación abierta (recomendado)",
    ["SETUP_WIZARD_KEEP_WATCH_BODY"] = "La vigilancia de puntuación es un pequeño panel de progreso de Midnight que aparece mientras pescas y tras actualizaciones de puntuación. Muestra progreso y objetivos útiles; esto la mantiene visible en vez de dejar que se oculte automáticamente.",
