    ["ACH_WAYPOINT_BUTTON"] = "Marcador: %s (%.1f, %.1f)",
    ["ACH_WAYPOINT_TOOLTIP"] = "Añade esta ubicación a TomTom si está disponible; de lo contrario, usa el marcador del mapa y la navegación de objetivos de Blizzard.",
